export default {
  modules: ['druxt-site', '@druxt-contrib/canvas'],
  druxt: {
    baseUrl: 'http://localhost:3005',
    proxy: { api: true },
  },
}

export default ({ $druxt, store }) => {
  $druxt.axios.interceptors.request.use((config) => {
    if (store.state.token) {
      config.headers.Authorization = `Bearer ${store.state.token}`
    }
    return config
  })
}

async fetch() {
  const resource = await this.$store.dispatch('druxt/getResource', {
    type: 'node--page',
    id: this.id,
  })
  if (resource.error?.statusCode === 401) {
    return this.$router.push('/user/login')
  }
  this.resource = resource
},
